 const client=createMayoristaClient({enabled:true,baseUrl,qaAislado,getSigoToken,expectedEmpresaId});let identity,tab=initialPage,data={},message='',busy=false,ready=false,destroyed=false,sharedResults={},profile=null,collectionPermission=null,filters={periodo:'mes'};
 const hostCommerce=qaAislado?undefined:sharedCommerce;sharedCommerce=hostCommerce;
 let disposeLaunch;
