 const stateLabel=s=>({recibido:'Recibido',aprobado:'Aprobado',pendiente:'Pendiente',picking:'En preparación',verificada:'Preparado',en_reparto:'Despachado',entregado:'Entregado',parcial:'Entrega parcial',rechazado:'No entregado',cerrada:'Cerrado',cancelada:'Anulado',requiere_autorizacion:'Requiere autorización',en_preparacion:'En preparación',con_faltantes:'Con faltantes',preparado:'Preparado',en_carga:'En carga',cargada:'En carga',no_entregado:'No entregado',devuelto:'Devuelto',cerrado:'Cerrado',anulado:'Anulado'})[s]??s;
