 function renderSharedCustomers(){return sharedNotice('Clientes')+form('route','Ruta / zona',choose('id','Registro',[['new','Nueva'],...options(data.plan.rutas)])+field('nombre','Nombre')+field('zona','Zona')+`<label>Días (0 domingo a 6 sábado, separados por coma)<input name="dias" placeholder="1,3,5"></label>`)+form('customer','Asignar cliente existente de SIGO',choose('id','Cliente',options(data.catalog.clientes))+choose('vendedorId','Vendedor',options(data.plan.vendedores.filter(v=>v.activo)))+choose('rutaId','Ruta',options(data.plan.rutas))+choose('listaId','Lista de precios',[['','Lista general'],...options(data.master.listas.filter(l=>l.activa))])+choose('habilitado','Toma de pedidos',[['true','Habilitada'],['false','Suspendida']])+field('orden','Orden de recorrido','number','0')+`<label>Latitud opcional<input name="latitud" type="number" step="any"></label><label>Longitud opcional<input name="longitud" type="number" step="any"></label>`)+data.catalog.clientes.slice(0,20).map(c=>`<article class="card"><h3>${esc(c.nombre)}</h3><button data-customer="${esc(c.id)}">Ficha comercial integral</button><p>${esc(c.documento)} · ${esc(c.direccion)} · ${esc(c.telefono)}</p><p>Vendedor: ${esc(data.plan.vendedores.find(v=>v.id===c.vendedorId)?.nombre??'Sin asignar')} · Ruta: ${esc(data.plan.rutas.find(r=>r.id===c.rutaId)?.nombre??'Sin asignar')}</p><p>Límite: ${money(Math.round(Number(c.limiteCredito??0)*100))} · Saldo: ${money(Math.round(Number(c.saldo??0)*100))}</p><details><summary>Historial de pedidos y visitas</summary>${data.orders.filter(o=>o.clienteId===c.id).map(o=>`<p>${esc(o.pedidoId)} · ${stateLabel(o.estado)} · ${esc(o.creadoEn)}</p>`).join('')}${(data.visits??[]).filter(v=>v.clienteId===c.id).map(v=>`<p>Visita: ${esc(v.motivo??v.resultado)} · ${esc(v.creadoEn)}</p>`).join('')}</details></article>`).join('');}
